use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread;
use semio_framework_value::{ByteReadSource,retirement::RetireOwned,retained_clone::RetainedCloneClose};
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:64}}
fn exact(p:RetainedCloneProgress,h:semio_framework_trace::HeapAllocationObservation){assert!(p.fits(grant()));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}
fn close<T:RetireOwned+Send+'static>(value:T)->(usize,usize){let mut slot=Some(value);let mut owner=RetainedCloneClose::default();let(mut born,mut freed)=(0,0);for index in 0..100000{if slot.is_none()&&owner.is_empty(){break}let d=if slot.is_some(){owner.next_owner_demands::<T>(true,&None,4096).unwrap()}else{RetirementDemand{copy_bytes:owner.next_copy_byte_demand().unwrap(),capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_release_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()}};let g=RetainedCloneGrant{maximum_copy_bytes:4096.max(d.copy_bytes),maximum_capacity_bytes:4096.max(d.capacity_bytes),maximum_release_bytes:4096.max(d.release_bytes),..grant()};let(p,h)=observe_heap_allocations_on_this_thread(||if slot.is_some(){owner.begin_granted(&mut slot,g).unwrap().unwrap().progress()}else{owner.step_granted(g).unwrap().progress()});assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=h.requested_bytes;freed+=h.released_bytes;assert!(index<99999)}(born,freed)}
#[test]
fn original_history_batch_message_preserves_wire_pages_and_cancellation_receipts(){let hex=include_str!("../../../../../../../🔨️modules/📡️replication/🚪️io/💾️binary/🔗️causal/🛫️native/📬️.hex").trim();let expected=hex.as_bytes().chunks(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect::<Vec<_>>();for wide in [false,true]{let mut input=semio_framework_os_spr::decode_envelopes(&expected).unwrap();if wide{let pattern=[0,1,127,128,254,255];let payload=(0..8197).map(|index|pattern[index%pattern.len()]).collect::<Vec<_>>();let previous=std::mem::replace(&mut input[0].diff.payload,semio_framework_os_spr::CausalPayload::try_from_slice(&payload).unwrap());close(previous);}let reference=semio_framework_os_spr::encode_envelopes(&input);if !wide{assert_eq!(reference,expected);}for cut in [0,1,3,17,63,127,512,usize::MAX]{let mut source=OriginalHistoryBatchMessage::new(262144,1048576).unwrap();let(mut born,mut freed)=(0,0);for index in 0..100000{if index==cut||source.ready(){break}let d=source.demands(4096).unwrap();for axis in 0..5{let mut g=grant();match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=d.copy_bytes.saturating_sub(1),2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4=>g.maximum_depth=0,_=>continue}let(p,h)=observe_heap_allocations_on_this_thread(||source.advance(&input,1,g).unwrap());assert_eq!(p,Default::default());exact(p,h);}if source.source.is_some(){let(error,h)=observe_heap_allocations_on_this_thread(||source.advance(&input,2,grant()).unwrap_err());assert_eq!(error.kind,ValueRefusalKind::InvariantViolated);assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let(p,h)=observe_heap_allocations_on_this_thread(||source.advance(&input,1,grant()).unwrap());exact(p,h);born+=h.requested_bytes;freed+=h.released_bytes;assert!(index<99999);}if cut==usize::MAX{assert!(source.ready());let((pages,p),h)=observe_heap_allocations_on_this_thread(||source.take(grant()).unwrap().unwrap());exact(p,h);let mut actual=vec![0;pages.byte_len()];assert_eq!(pages.read_bytes(0,&mut actual),actual.len());assert_eq!(actual,reference);let(b,f)=close(pages);born+=b;freed+=f;}for index in 0..100000{if source.terminal_is_empty(){break}let(p,h)=observe_heap_allocations_on_this_thread(||source.close_step(grant()).unwrap().progress());exact(p,h);born+=h.requested_bytes;freed+=h.released_bytes;assert!(index<99999);}assert!(source.terminal_is_empty());assert_eq!(born,freed);}close(input);}}
